{
  "schema": 1,
  "scope": "Supplementary same-parameter provenance acceptance and four intentional owner refusals. No primary or inventory credit. Native accepts all inputs; owner refusals are not Native agreements.",
  "options": {
    "target": "ES5",
    "module": "CommonJS",
    "strict": true,
    "declaration": true,
    "noEmitOnError": true,
    "lib": [
      "ES5"
    ],
    "outDir": "dist"
  },
  "typescript": "5.9.3",
  "implementationSha256": "3ae902c92cc44dace175c0e69e13a4b0899f6983c6121d76b9ab8dd5795e7675",
