  "cases": [
    {
      "id": "same-parameter-projection",
      "accepts": true,
      "diagnostics": [],
      "declarations": {
        "main.d.ts": "export declare function result<T extends unknown[]>(value: T): T;\n"
      },
      "source": "export function result<T extends unknown[]>(value: T): T { return [value[0]] as unknown as T; }\n",
      "blueAccepts": true
    },
    {
      "id": "unknown-cannot-acquire-parameter",
      "accepts": true,
      "diagnostics": [],
      "declarations": {
        "main.d.ts": "export declare function result<T>(value: unknown): T;\n"
      },
      "source": "export function result<T>(value: unknown): T { return value as unknown as T; }\n",
      "blueAccepts": false
    },
    {
      "id": "readonly-cannot-acquire-parameter",
      "accepts": true,
      "diagnostics": [],
      "declarations": {
        "main.d.ts": "export declare function result<T>(value: readonly string[]): T;\n"
      },
      "source": "export function result<T>(value: readonly string[]): T { return value as unknown as T; }\n",
      "blueAccepts": false
    },
    {
      "id": "unrelated-parameter-projection",
      "accepts": true,
      "diagnostics": [],
      "declarations": {
        "main.d.ts": "export declare function result<T extends unknown[], U>(value: T): U;\n"
      },
      "source": "export function result<T extends unknown[], U>(value: T): U { return [value[0]] as unknown as U; }\n",
      "blueAccepts": false
    },
    {
      "id": "mixed-concrete-readonly-payload",
      "accepts": true,
      "diagnostics": [],
      "declarations": {
        "main.d.ts": "export declare function result<T extends unknown[]>(value: T, protectedValue: readonly string[]): T;\n"
      },
      "source": "export function result<T extends unknown[]>(value: T, protectedValue: readonly string[]): T { return [value[0], protectedValue] as unknown as T; }\n",
      "blueAccepts": false
    }
  ]
}
